mkdir -p src/Analyzer/Graph/Declaration && cat > src/Analyzer/Graph/Declaration/Visibility.php <<'PHP'
<?php

declare(strict_types=1);

namespace App\Analyzer\Graph\Declaration;

/**
 * How widely a declaration may be named from other code.
 *
 * Visibility is the first thing an impact question asks about a member. A private
 * method can only be reached from inside the class that declares it, so changing it
 * cannot break anything the analysis did not already see; a public one can be
 * reached by code that was never analysed at all. Naming the three levels as a
 * closed type is what lets a query say "the public methods of this controller"
 * without the query having to know how PHP spells a modifier.
 *
 * A declaration that carries no visibility — a function, a class — has none of these
 * rather than a fourth case, because "not applicable" is the absence of a value and
 * not a value of its own.
 */
enum Visibility: string
{
    /** Reachable from anywhere */
    case Public = 'public';

    /** Reachable from the declaring class-like and those that inherit it */
    case Protected = 'protected';

    /** Reachable only from the declaring class-like */
    case Private = 'private';
}
PHP
cat > src/Analyzer/Graph/Declaration/Modifiers.php <<'PHP'
<?php

declare(strict_types=1);

namespace App\Analyzer\Graph\Declaration;

/**
 * The keywords a declaration carries besides its visibility.
 *
 * PHP writes these as a set of independent flags rather than as one choice: a method
 * may be both final and static, a class both abstract and never final. They are kept
 * together as one value because they are read together — "the abstract methods", "the
 * readonly properties" — and because a declaration that carries none of them is still
 * a declaration with modifiers, all of them false, rather than a declaration with no
 * modifiers at all.
 *
 * Only the keywords that survive into the analysed graph are here. `readonly` on a
 * class and `readonly` on a property are the same keyword answering the same
 * question, so they share one field.
 */
final class Modifiers
{
    /**
     * @param bool $static   Whether the declaration belongs to the class rather than to an instance
     * @param bool $abstract Whether the declaration has no body and must be provided by a subclass
     * @param bool $final    Whether the declaration may not be overridden
     * @param bool $readonly Whether the declaration may only be written once
     */
    public function __construct(
        public readonly bool $static = false,
        public readonly bool $abstract = false,
        public readonly bool $final = false,
        public readonly bool $readonly = false,
    ) {}

    /**
     * Reports whether the declaration carries no modifier at all.
     *
     * A declaration with nothing written on it is the common case, and telling it
     * apart from one that is merely not abstract is what lets a report leave the
     * whole group out rather than print four falses.
     *
     * @example A plain declaration carries nothing
     *     (new \App\Analyzer\Graph\Declaration\Modifiers())->none() // => true
     * @example One keyword is enough to be worth reporting
     *     (new \App\Analyzer\Graph\Declaration\Modifiers(static: true))->none() // => false
     *
     * @return bool True when no modifier is set
     */
    public function none(): bool
    {
        return !$this->static && !$this->abstract && !$this->final && !$this->readonly;
    }
}
